@if (IsLoading)
{
    <div class="d-flex justify-content-center align-items-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
        <span class="ms-2">Loading products...</span>
    </div>
}
else if (ErrorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @ErrorMessage
    </div>
}
else if (Result is null || Result.Items.Count == 0)
{
    <div class="text-center py-5 text-muted">
        <h5>No products found</h5>
        <p>Try adjusting your filters.</p>
    </div>
}
else
{
    <!-- Toolbar -->
    <div class="d-flex justify-content-between align-items-center mb-3">
        <div>
            <label class="me-2 fw-bold" for="sort-select">Sort by:</label>
            <select id="sort-select" class="form-select form-select-sm d-inline-block w-auto"
                    value="@SortBy" @onchange="HandleSortChange">
                <option value="price_asc">Price: Low to High</option>
                <option value="price_desc">Price: High to Low</option>
                <option value="name_asc">Name: A-Z</option>
                <option value="rating_desc">Rating: Highest</option>
            </select>
        </div>
        <span class="text-muted">
            Showing @(_startItem)–@(_endItem) of @Result.TotalCount products
        </span>
    </div>

    <!-- Product Grid -->
    <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3 mb-4">
        @foreach (var product in Result.Items)
        {
            <div class="col">
                <ProductCard Product="product"
                             OnSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />
            </div>
        }
    </div>

    <!-- Pagination -->
    @if (_totalPages > 1)
    {
        <Pagination CurrentPage="Result.Page"
                    TotalPages="_totalPages"
                    OnPageChanged="HandlePageChanged" />
    }
}

@code {
    [Parameter]
    public PagedResult<Product>? Result { get; set; }

    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public bool IsLoading { get; set; }

    [Parameter]
    public string? ErrorMessage { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private int _totalPages => Result is null || Result.PageSize == 0
        ? 0
        : (int)Math.Ceiling((double)Result.TotalCount / Result.PageSize);

    private int _startItem => Result is null || Result.TotalCount == 0
        ? 0
        : (Result.Page - 1) * Result.PageSize + 1;

    private int _endItem => Result is null
        ? 0
        : Math.Min(Result.Page * Result.PageSize, Result.TotalCount);

    private async Task HandleSortChange(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "price_asc";
        await OnSortChanged.InvokeAsync(value);
    }

    private async Task HandlePageChanged(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }
}

@page "/catalog"
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<h3 class="mb-4">Product Catalog</h3>

<div class="row">
    <!-- Filter Sidebar -->
    <div class="col-md-3">
        <ProductFilterPanel Categories="_categories"
                            OnApplyFilters="HandleApplyFilters"
                            OnClearFilters="HandleClearFilters" />
    </div>

    <!-- Main Content -->
    <div class="col-md-9">
        <ProductGrid Result="_result"
                     SortBy="@_sortBy"
                     IsLoading="_isLoading"
                     ErrorMessage="@_errorMessage"
                     OnSortChanged="HandleSortChanged"
                     OnPageChanged="HandlePageChanged"
                     OnProductSelected="OnProductSelected"
                     OnAddToCart="HandleAddToCart" />
    </div>
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 9;
    private bool _isLoading;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAndProducts();
    }

    private async Task LoadCategoriesAndProducts()
    {
        _isLoading = true;
        _errorMessage = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            _result = productsTask.Result;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to load products. {ex.Message}";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task SearchProducts()
    {
        _isLoading = true;
        _errorMessage = null;

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to load products. {ex.Message}";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleClearFilters()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchProducts();
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart functionality
        return Task.CompletedTask;
    }
}

